CREATE COLUMN TABLE "TEST_AP"."CUFD" ("TableID" NVARCHAR(21) NOT NULL , "FieldID" SMALLINT CS_INT NOT NULL , "AliasID" NVARCHAR(50) NOT NULL , "Descr" NVARCHAR(80), "TypeID" NVARCHAR(1), "EditType" NVARCHAR(1), "SizeID" SMALLINT CS_INT, "EditSize" SMALLINT CS_INT, "Dflt" NVARCHAR(254), "NotNull" NVARCHAR(1) DEFAULT 'N', "IndexID" NVARCHAR(1) DEFAULT 'N', "RTable" NVARCHAR(21), "RField" SMALLINT CS_INT, "Action" NVARCHAR(1), "Sys" NVARCHAR(1) DEFAULT 'N', "DfltDate" LONGDATE CS_LONGDATE, "RelUDO" NVARCHAR(20), "ValidRule" NVARCHAR(254), "RelSO" NVARCHAR(20), "RThrdPTab" NVARCHAR(100), "RThrdPFld" NVARCHAR(100), PRIMARY KEY ("TableID", "FieldID")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "CUFD_ALIAS" ON "TEST_AP"."CUFD" ( "TableID" ASC, "AliasID" ASC )